<template>
  <PageWrapper :title="t('crud.order.page.title', 'order')">
<SchemaTablePage ref="buttonTable" class="min-w-0 flex-1" storage-key="generated-order" :schema="tableSchema" :query="query" :rows="list" :total="total" :loading="loading" :lock="buttonLock" :context="{ values: {}, permissions: buttonUser.permissions, handlers: {} }" @refresh="refreshButtonHost" @sort-change="({ prop, order }) => { query.sort = prop ?? ''; query.order = order === 'descending' ? 'desc' : 'asc'; loadData(); }" @selection-change="handleSelectionChange">      <template #search><SearchForm :model="query" :loading="loading" @search="onSearch" @reset="onReset"><el-form-item :label="t('crud.order.field.field_1', '单行输入')"><el-select v-if="filterNodes.some(node => node.id === 'field1' && node.dataSource?.kind && node.dataSource.kind !== 'static')" v-model="query.field1" :placeholder="filterOptions.placeholder('field1') || t('crud.order.search.select', '请选择')" :loading="filterOptions.pending.value.field1" clearable><el-option v-for="option in filterOptions.supplied.value.field1 ?? []" :key="String(option.value)" :label="option.label" :value="option.value as string | number" /></el-select><el-input v-else v-model="query.field1" :placeholder="t('crud.order.search.input', { label: t('crud.order.field.field_1', '单行输入') }, { default: '请输入{label}' })" clearable /></el-form-item></SearchForm></template>
<template #toolbar><ListButtonBar :buttons="toolbarButtons" :handlers="buttonHandlers" :allowed="toolbarButtonAllowed" :lock="buttonLock" :refresh="refreshButtonHost" :context="buttonContext('toolbar')" :context-version="buttonContextVersion" :permission-check="buttonPermission" :clear-selection="clearButtonSelection" :close="closeButtonHost" /><input ref="fileInput" class="hidden" type="file" accept=".csv,text/csv" @change="importCsv" /></template><template #id="scope"><span>{{ presentField('id', scope.row) }}</span></template><template #field1="scope"><span>{{ presentField('field1', scope.row) }}</span></template><template #field2="scope"><span>{{ presentField('field2', scope.row) }}</span></template><template #field3="scope"><span>{{ presentField('field3', scope.row) }}</span></template><template #field5="scope"><span>{{ presentField('field5', scope.row) }}</span></template><template #field5Copy="scope"><span>{{ presentField('field5Copy', scope.row) }}</span></template><template #actions="scope"><ListButtonBar :buttons="rowButtons" :handlers="buttonHandlers" :allowed="buttonAllowed" :row="scope.row" :values="buttonValues(scope.row)" :fields="Object.keys(buttonFieldMap)" :lock="buttonLock" :refresh="refreshButtonHost" :context="buttonContext('row', scope.row)" :context-version="buttonContextVersion" :permission-check="buttonPermission" :clear-selection="clearButtonSelection" :close="closeButtonHost" link /></template></SchemaTablePage><OrderForm :lock="buttonLock" v-model="dialogVisible" :row="current" @success="refreshAfterSave" /><OrderDetail v-model="drawerVisible" :row="current" />
  </PageWrapper>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, reactive, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { useI18n } from 'vue-i18n';
import { useCrud } from '@/composables/useCrud';
import { downloadCsv, parseCsv, readFileAsText, toCsv, type CsvColumn } from '@/utils/csv';
import { hasPermission } from '@/utils/permission';
